import React from "react";
import { useNavigate } from "react-router-dom";

export default function StudentDashboard({ logout, user }) {
  const navigate = useNavigate();

  const actions = [
    { title: "View Candidates", desc: "Browse the list of approved candidates and their positions.", path: "/candidates" },
    { title: "Cast Vote", desc: "Securely cast your vote using OTP verification.", path: "/vote" },
    { title: "Register Candidacy", desc: "Submit your requirements to apply as a candidate.", path: "/register-candidacy" },
    { title: "Election Results", desc: "View real-time turnout and final election results.", path: "/results" },
    { title: "Profile & Security", desc: "Manage your account details and two-factor authentication.", path: "/profile" },
  ];

  const handleLogout = () => {
    if (logout) logout();
    navigate("/login");
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Top bar */}
      <header className="bg-white shadow-md border-b border-gray-200">
        <div className="max-w-7xl mx-auto flex justify-between items-center px-6 py-4">
          {/* Logo */}
          <div
            onClick={() => navigate("/student-dashboard")}
            className="text-2xl font-bold text-blue-600 cursor-pointer"
          >
            iVote Portal
          </div>

          {/* Right side */}
          <div className="flex items-center gap-4">
            {user && <span className="text-gray-700 hidden sm:inline">Hi, {user.name}</span>}
            <button
              onClick={handleLogout}
              className="bg-red-500 text-white px-4 py-2 rounded-lg hover:bg-red-600 transition"
            >
              Logout
            </button>
          </div>
        </div>
      </header>

      {/* Content */}
      <main className="max-w-7xl mx-auto py-10 px-6">
        <header className="mb-10 text-center">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">Student Dashboard</h1>
          <p className="text-gray-600">Access your election tools and account features</p>
        </header>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {actions.map((a, i) => (
            <div
              key={i}
              onClick={() => navigate(a.path)}
              className="bg-white border border-gray-200 rounded-xl shadow-sm p-6 cursor-pointer hover:shadow-md transition"
            >
              <h2 className="text-lg font-semibold text-blue-600 mb-2">{a.title}</h2>
              <p className="text-gray-600 text-sm">{a.desc}</p>
            </div>
          ))}
        </div>
      </main>
    </div>
  );
}
